#!/bin/sh
# A small human-readable status file, generated by the real guest probe.
# This is browser-local; it never opens websites or changes TLS validation.
set -u
CORE=/usr/local/libexec/puppy50-network-probe-core
PAGE=/run/puppy50-network-status.html
mkdir -p /run
if [ ! -x "$CORE" ]; then
  STATUS=30
else
  "$CORE"
  STATUS=$?
fi
MODE=offline
DETAIL="No verified Internet connection. Connect your HOST to a network, then restart this experimental VM."
TITLE="Offline or unavailable"
case "$STATUS" in
  0)
    TITLE="Public HTTPS verified"
    MODE="$(cat /run/puppy50-network-mode 2>/dev/null || echo unknown)"
    case "$MODE" in
      proxy) DETAIL="HTTPS is connected through the host-only TLS-preserving CONNECT bridge. The guest verifies the website certificate." ;;
      direct) DETAIL="HTTPS is connected directly through QEMU user-mode networking. The guest verifies the website certificate." ;;
      *) DETAIL="A HTTPS check passed but the route was not identified." ;;
    esac
    ;;
  20) DETAIL="The guest's virtual Ethernet adapter was not detected. Check that QEMU was started with e1000 networking." ;;
  21) DETAIL="No DHCP address was obtained from QEMU's virtual network." ;;
  22) DETAIL="No default network route was found." ;;
  23) DETAIL="DNS resolution failed." ;;
  25) DETAIL="A network address exists, but the public HTTPS test failed. The host may be offline, behind a captive portal, or restricting traffic." ;;
esac
# No user-controlled input is embedded in this HTML file: all variants above
# are fixed in source. This prevents network-derived content injection.
TMP=/run/.puppy50-status-new.$$
cat > "$TMP" <<EOF
<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Puppy50 | Network status</title><style>
body{font:17px system-ui,sans-serif;background:#071020;color:#f1f6ff;padding:32px;max-width:800px;margin:auto;line-height:1.7}
h1{color:#09c6ce}p{color:#c2d5e8}a{color:#70d9ee}
section{background:#12243e;padding:25px;border-radius:14px;border:1px solid #36516b}
</style></head><body><h1>Puppy50 Network Status</h1><section>
<h2>$TITLE</h2><p>$DETAIL</p><p>Guest test result: $STATUS · Mode: $MODE</p>
</section><p>Switch Wi-Fi, Ethernet, VPN or hotspot settings on the host computer. The guest does not select physical Wi-Fi networks.</p>
<p>This is a startup snapshot, not live monitoring; reboot the VM after changing the host network if a new connection test is required.</p>
<a href="file:///usr/share/puppy50web/index.html">Back to Puppy50 home</a></body></html>
EOF
chmod 644 "$TMP"
mv "$TMP" "$PAGE"
echo "PUPPY50_V70_NETWORK_STATUS_PAGE_WRITTEN=PASS code=$STATUS mode=$MODE" >/dev/ttyS0 2>/dev/null || true
exit "$STATUS"
